import inspect
import asyncio
from functools import wraps, partial

def iscoroutinefunction(func):
    return inspect.iscoroutinefunction(func)

def isasyncgenfunction(func):
    return inspect.isasyncgenfunction(func)

def isgeneratorfunction(func):
    return inspect.isgeneratorfunction(func)

def check_chain(call, check_func):
    curr = call
    visited = set()
    while curr is not None:
        if id(curr) in visited:
            break
        visited.add(id(curr))
        if check_func(curr):
            return True
        dunder_call = getattr(curr, "__call__", None)
        if dunder_call and check_func(dunder_call):
            return True
        unwrapped = inspect.unwrap(curr)
        if unwrapped is not curr:
            curr = unwrapped
            continue
        if isinstance(curr, partial):
            curr = curr.func
            continue
        break
    return False

